surface_set_target(min_surf)

draw_set_color(c_dkgray)
with(obj_unit)
{
    if (4>global.player_control and 4>player) or (global.player_control>=4 and player>=4) or global.map_heck{draw_circle(min_fog_xx*other.xscale, min_fog_yy*other.yscale, range*other.mscale_back, 0)}
}

draw_set_color(c_black)
with(obj_unit)
{
    if (4>global.player_control and 4>player) or (global.player_control>=4 and player>=4) or global.map_heck
    {
        min_fog_xx=x
        min_fog_yy=y
        if 0<bbox_right and 0<bbox_bottom and bbox_left<room_width and bbox_top<room_height
        {
            draw_circle(x*other.xscale, y*other.yscale, range*other.mscale_back, 0)
        }
    }
}

